const b = $json.body || $json;
const lead = {
  leadId: `L-${Date.now()}`,
  nombre: String(b.nombre || b.name || '').trim(),
  email: String(b.email || '').trim().toLowerCase(),
  mensaje: String(b.mensaje || b.message || '').trim(),
  marca: String(b.marca || b.brand || '').trim(),
  origen: String(b.origen || 'landing').trim(),
  at: new Date().toISOString(),
};
if (!lead.email && !lead.nombre) {
  return [{ json: { ok: false, error: 'falta nombre o email', lead } }];
}
return [{ json: { ok: true, lead, action: 'lead.append' } }];

const prev = $json;
const lead = prev.lead || (($('Normalizar lead').first().json || {}).lead);
return [{ json: {
  ok: true,
  sistema: 'embudo-live',
  lead,
  runner: prev,
  siguiente: 'Revisión humana (20%): contactar lead. Pedile a Cursor copy de respuesta si hace falta.',
  at: new Date().toISOString()
}}];
